package com.example.analytics; import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import java.time.Instant; import java.util.*; import jakarta.validation.constraints.NotBlank; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/analytics") public class AnalyticsController {private final ClickEventRepository repo; public AnalyticsController(ClickEventRepository r){repo=r;} public record ClickRequest(@NotBlank String code,String referrer,String clickedAt){} @PostMapping("/clicks") public ResponseEntity<Void> click(@Valid @RequestBody ClickRequest r){Instant t;try{t=r.clickedAt()==null?Instant.now():Instant.parse(r.clickedAt());}catch(Exception e){t=Instant.now();}repo.save(new ClickEvent(r.code(),r.referrer()==null?"direct":r.referrer(),t));return ResponseEntity.accepted().build();} @GetMapping("/{code}") public Map<String,Object> stats(@PathVariable String code){List<ClickEvent> recent=repo.findTop100ByCodeOrderByClickedAtDesc(code);Map<String,Long> refs=new HashMap<>();repo.findAll().stream().filter(e->e.code.equals(code)).forEach(e->refs.merge(e.referrer==null?"direct":e.referrer,1L,Long::sum));return Map.of("code",code,"totalClicks",repo.countByCode(code),"referrers",refs,"recentClicks",recent.stream().map(e->Map.of("clickedAt",e.clickedAt,"referrer",e.referrer==null?"direct":e.referrer)).toList());}}